int spuckCharacter = 0;  // upstream: x - which portrait/character is shown (0=BAR,1=NERUAL,2=LEXAN,3=VISINE,4=BIFF,5=BEJIN)
int spuckAnimTimer = 0;  // upstream: y - drives the automatic idle-animation frame cycling
int spuckAnimFrame = 0;  // upstream: StatAnim - current idle-animation frame (0-2)

enum SpuckState
{
    SPUCK_STATE_TITLE = 0,
    SPUCK_STATE_GALLERY = 1
};

int spuckState;

void spuckBeginTitle()
{
    spuckState = SPUCK_STATE_TITLE;
}

void spuckBeginGallery()
{
    spuckState = SPUCK_STATE_GALLERY;
}

// Upstream's own real `gb.titleScreen(F(""), intro)` call: an empty title
// string plus the real "intro" logo bitmap - restored here via
// gbDrawBitmap() in place of this file's own former placeholder "SHUFFLE"/
// "PUCK CAFE" text (see this file's own header comment). Centered
// horizontally ((84-64)/2 = 10); "PRESS A" (this shim's own explicit
// resumable-state prompt, matching gamePong.c's own precedent) sits
// directly below it.
void spuckUpdateTitle()
{
    gbSetColor( 1 );
    gbFontSize = 1;

    gbDrawBitmap( 10, 2, spuckIntroBitmap );

    gbCursorX = 14;
    gbCursorY = 40;
    gbPrintString( "PRESS A" );

    if( gbPressed( BTN_A ) )
      spuckBeginGallery();
}

// Real upstream bitmap portraits, restored (see this file's own header
// comment). Mirrors upstream's own per-character `BAR[]`/`NERUAL[]`/
// `LEXAN[]`/`VISINE[]`/`BIFF[]`/`BEJIN[]` arrays-of-3 indexed by
// spuckAnimFrame (upstream: StatAnim), drawn at upstream's own exact
// `gb.display.drawBitmap(0, 0, ...)` coordinates - none of upstream's own
// real call sites use rotation/flip, so plain gbDrawBitmap() suffices.
void spuckDrawCharacter()
{
    gbSetColor( 1 );

    if( spuckCharacter == 0 )
    {
        if( spuckAnimFrame == 0 ) gbDrawBitmap( 0, 0, spuckBarBitmap );
        else if( spuckAnimFrame == 1 ) gbDrawBitmap( 0, 0, spuckBar2Bitmap );
        else gbDrawBitmap( 0, 0, spuckBar3Bitmap );
    }
    else if( spuckCharacter == 1 )
    {
        if( spuckAnimFrame == 0 ) gbDrawBitmap( 0, 0, spuckNerualBitmap );
        else if( spuckAnimFrame == 1 ) gbDrawBitmap( 0, 0, spuckNerual2Bitmap );
        else gbDrawBitmap( 0, 0, spuckNerual3Bitmap );
    }
    else if( spuckCharacter == 2 )
    {
        if( spuckAnimFrame == 0 ) gbDrawBitmap( 0, 0, spuckLexanBitmap );
        else if( spuckAnimFrame == 1 ) gbDrawBitmap( 0, 0, spuckLexan2Bitmap );
        else gbDrawBitmap( 0, 0, spuckLexan3Bitmap );
    }
    else if( spuckCharacter == 3 )
    {
        if( spuckAnimFrame == 0 ) gbDrawBitmap( 0, 0, spuckVisineBitmap );
        else if( spuckAnimFrame == 1 ) gbDrawBitmap( 0, 0, spuckVisine2Bitmap );
        else gbDrawBitmap( 0, 0, spuckVisine3Bitmap );
    }
    else if( spuckCharacter == 4 )
    {
        if( spuckAnimFrame == 0 ) gbDrawBitmap( 0, 0, spuckBiffBitmap );
        else if( spuckAnimFrame == 1 ) gbDrawBitmap( 0, 0, spuckBiff2Bitmap );
        else gbDrawBitmap( 0, 0, spuckBiff3Bitmap );
    }
    else
    {
        if( spuckAnimFrame == 0 ) gbDrawBitmap( 0, 0, spuckBejinBitmap );
        else if( spuckAnimFrame == 1 ) gbDrawBitmap( 0, 0, spuckBejin2Bitmap );
        else gbDrawBitmap( 0, 0, spuckBejin3Bitmap );
    }
}

// Ported directly from upstream's own y/StatAnim idle-cycle logic (see
// this file's own header comment - the exact thresholds are load-bearing).
void spuckAdvanceAnimation()
{
    spuckAnimTimer = spuckAnimTimer + 1;
    if( spuckAnimTimer < 15 ) spuckAnimFrame = 0;
    if( spuckAnimTimer > 30 && spuckAnimTimer < 45 ) spuckAnimFrame = 1;
    if( spuckAnimTimer > 45 && spuckAnimTimer < 60 ) spuckAnimFrame = 2;
    if( spuckAnimTimer > 60 ) spuckAnimTimer = 0;
}

void spuckUpdateGallery()
{
    // upstream: pressing C re-runs setup(), which re-shows the (blocking)
    // title screen without resetting x/y/StatAnim - ported as returning to
    // the title state while leaving spuckCharacter/spuckAnimTimer/
    // spuckAnimFrame untouched, matching gamePong.c's own precedent for a
    // mid-play C press.
    if( gbPressed( BTN_C ) )
    {
        spuckBeginTitle();
        return;
    }

    spuckDrawCharacter();

    spuckAdvanceAnimation();

    // manual animation stepping
    if( gbPressed( BTN_A ) )
    {
        spuckAnimFrame = spuckAnimFrame + 1;
        if( spuckAnimFrame == 1 ) spuckAnimTimer = 31;
        if( spuckAnimFrame == 2 ) spuckAnimTimer = 46;
        if( spuckAnimFrame == 3 ) spuckAnimTimer = 0;
        if( spuckAnimFrame < 0 ) spuckAnimFrame = 0;
        if( spuckAnimFrame > 2 ) spuckAnimFrame = 2;
    }

    // character switching
    if( gbPressed( BTN_RIGHT ) )
    {
        spuckCharacter = spuckCharacter + 1;
        spuckAnimTimer = 0; // reset animation to 1st frame
        if( spuckCharacter > 5 ) spuckCharacter = 5;
    }
    if( gbPressed( BTN_LEFT ) )
    {
        // upstream quirk, preserved exactly: this clamps at 1, not 0 - see
        // this file's own header comment.
        spuckCharacter = spuckCharacter - 1;
        spuckAnimTimer = 0; // reset animation to 1st frame
        if( spuckCharacter < 1 ) spuckCharacter = 1;
    }
    if( gbPressed( BTN_B ) )
    {
        // press B to return to the "bar" screen
        spuckCharacter = 0;
        spuckAnimTimer = 0; // reset animation to 1st frame
    }
}

void gameShufflepuck_init()
{
    gbBegin();
    spuckCharacter = 0;
    spuckAnimTimer = 0;
    spuckAnimFrame = 0;
    spuckBeginTitle();
}

void gameShufflepuck_update()
{
    if( !gbUpdate() ) return;

    if( spuckState == SPUCK_STATE_TITLE ) spuckUpdateTitle();
    else spuckUpdateGallery();

    gbRenderFrame();
}
